package com.asmj.marketplace.insurance.controller; import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.insurance.model.*;import com.asmj.marketplace.insurance.service.InsuranceMarketplaceService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/insurance") @RequiredArgsConstructor public class InsuranceAdminController { final InsuranceMarketplaceService s; @GetMapping("/plans") public ApiResponse<List<InsurancePlan>> plans(){return ApiResponse.ok("Insurance plans",s.adminPlans());} @PutMapping("/plans/{id}/approval") public ApiResponse<InsurancePlan> approve(@PathVariable String id,@RequestParam boolean approved){return ApiResponse.ok(approved?"Insurance plan approved":"Insurance plan rejected",s.approve(id,approved));} @GetMapping("/quotes") public ApiResponse<List<InsuranceQuoteRequest>> quotes(){return ApiResponse.ok("Insurance quotes",s.adminQuotes());} }
